using System;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using Valle.Lan;
class Check {
 static int count;static void Assert(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS: "+name);count++;}
 static void Main(){var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var raw=new TcpClient();raw.Connect(IPAddress.Loopback,port);var peer=new LanPeer(listener.AcceptTcpClient());var stream=raw.GetStream();string message="{\"type\":\"hello\",\"name\":\"Jugador ñ\"}";var body=Encoding.UTF8.GetBytes(message);var head=BitConverter.GetBytes(IPAddress.HostToNetworkOrder(body.Length));for(int i=0;i<4;i++)stream.Write(head,i,1);for(int i=0;i<body.Length;i++)stream.Write(body,i,1);string received=null;for(int i=0;i<100&&!peer.Incoming.TryDequeue(out received);i++)Thread.Sleep(10);Assert(received==message,"Fragmented header/body and UTF-8 decoded correctly");peer.Send(message);var response=new byte[4+body.Length];int n=0;while(n<response.Length)n+=stream.Read(response,n,response.Length-n);Assert(Encoding.UTF8.GetString(response,4,body.Length)==message,"Length-prefixed outgoing frames");head=BitConverter.GetBytes(IPAddress.HostToNetworkOrder(70000));stream.Write(head,0,4);for(int i=0;i<100&&!peer.Closed;i++)Thread.Sleep(10);Assert(peer.Closed,"Oversized message closes peer");Assert(LanTransport.IsLocal(IPAddress.Parse("192.168.1.5"))&&!LanTransport.IsLocal(IPAddress.Parse("8.8.8.8")),"Only local target addresses accepted");raw.Close();peer.Dispose();listener.Stop();Console.WriteLine(count+" transport checks passed");}
}
